export const GOODS=[{id:'saffron',name:'Saffron',desc:'A spice worth its weight in gold',icon:'✺'},{id:'silk',name:'Silk',desc:'Fine cloth from the eastern shores',icon:'▧'},{id:'timber',name:'Timber',desc:'Seasoned wood for ships and homes',icon:'▥'},{id:'wine',name:'Wine',desc:'Sun-ripened Aurelia vintage',icon:'♧'}];
export const PORTS=[{id:'aurelia',name:'Port Aurelia',kind:'MERCHANT REPUBLIC',x:-22,z:-13,r:16,harbor:{x:-7,z:5},prices:{saffron:80,silk:160,timber:24,wine:45},color:'#c19e6b',description:'Terracotta rooftops, salt in the air, and a market alive with opportunity.'},{id:'bellhaven',name:'Bellhaven',kind:'THE NORTHERN KINGDOM',x:28,z:-36,r:12,harbor:{x:28,z:-20},prices:{saffron:145,silk:125,timber:42,wine:68},color:'#91b7a1',description:'Beyond the lighthouse, northern merchants pay handsomely for southern spices.'},{id:'verdant',name:'Verdant Cay',kind:'FREE PORT',x:38,z:30,r:10,harbor:{x:26,z:33},prices:{saffron:110,silk:210,timber:18,wine:35},color:'#a8bf79',description:'A sheltered palm-lined cove, home to shipwrights and independent traders.'}];
export const RUIN={x:-37,z:44,r:8,name:'The Sunken Observatory'};
export function newGame(){return{version:1,gold:1200,supplies:30,hull:100,cargo:{saffron:0,silk:0,timber:0,wine:0},x:0,z:12,heading:-.55,time:480,quest:0,discovered:[],log:['Day 1 — Took command of The Wayfarer at Port Aurelia.'],sail:0};}
export function cargoCount(s){return Object.values(s.cargo).reduce((a,b)=>a+b,0);}
export function trade(s,port,id,side){if(!GOODS.some(g=>g.id===id))return{ok:false,message:'Unknown cargo.'};const price=side==='buy'?port.prices[id]:Math.floor(port.prices[id]*.85);if(side==='buy'){if(cargoCount(s)>=40)return{ok:false,message:'Your hold is full. Sell cargo to make room.'};if(s.gold<price)return{ok:false,message:'Not enough gold.'};s.gold-=price;s.cargo[id]++;if(s.quest===0&&s.cargo.saffron>=3){s.quest=1;s.log.push('Bought the saffron. Set course for Bellhaven.');}}else if(side==='sell'){if(!s.cargo[id])return{ok:false,message:'None of this cargo in your hold.'};s.cargo[id]--;s.gold+=price;if(id==='saffron'&&port.id==='bellhaven'&&s.quest===1){s.delivered=(s.delivered||0)+1;if(s.delivered>=3){s.quest=2;s.gold+=500;s.log.push('Delivered saffron to Bellhaven. Earned a 500 gold commission.');return{ok:true,message:'Commission complete! +500 gold. Seek the Sunken Observatory.'};}}}else return{ok:false,message:'Invalid trade.'};return{ok:true,message:`${side==='buy'?'Bought':'Sold'} ${GOODS.find(g=>g.id===id).name} for ${price} gold.`};}
export function loadGame(storage){try{const s=JSON.parse(storage.getItem('horizon-save'));if(!s||s.version!==1)return newGame();const valid=Number.isFinite(s.gold)&&s.gold>=0&&Number.isFinite(s.x)&&Math.abs(s.x)<=100&&Number.isFinite(s.z)&&Math.abs(s.z)<=100&&Number.isFinite(s.heading)&&Number.isFinite(s.time)&&Number.isFinite(s.supplies)&&s.supplies>=0&&Number.isFinite(s.hull)&&s.hull>0&&s.hull<=100&&[0,1,2,3].includes(s.quest)&&Array.isArray(s.log)&&Array.isArray(s.discovered)&&GOODS.every(g=>Number.isInteger(s.cargo?.[g.id])&&s.cargo[g.id]>=0)&&cargoCount(s)<=40;return valid?{...newGame(),...s,sail:0}:newGame();}catch{return newGame();}}
export function saveGame(storage,s){try{storage.setItem('horizon-save',JSON.stringify(s));return true;}catch{return false;}}
